import React, { createContext, useContext, useState, useEffect, ReactNode } from 'react';

// Типи для авторизації
export interface TelegramUser {
  id: number;
  first_name: string;
  last_name?: string;
  username?: string;
  photo_url?: string;
  auth_date: number;
  hash: string;
}

export interface User {
  id: string;
  username: string;
  firstName: string;
  lastName?: string;
  photoUrl?: string;
  role: 'admin' | 'user' | 'viewer';
  permissions: string[];
  sessionId: string;
  loginTime: Date;
  lastActivity: Date;
}

export interface AuthState {
  isAuthenticated: boolean;
  user: User | null;
  isLoading: boolean;
  error: string | null;
}

export interface AuthContextType {
  auth: AuthState;
  login: (telegramData: TelegramUser) => Promise<boolean>;
  logout: () => void;
  refreshAuth: () => Promise<void>;
  clearError: () => void;
}

const AuthContext = createContext<AuthContextType | undefined>(undefined);

export const useAuth = (): AuthContextType => {
  const context = useContext(AuthContext);
  if (!context) {
    throw new Error('useAuth must be used within an AuthProvider');
  }
  return context;
};

interface AuthProviderProps {
  children: ReactNode;
}

export const AuthProvider: React.FC<AuthProviderProps> = ({ children }) => {
  const [auth, setAuth] = useState<AuthState>({
    isAuthenticated: false,
    user: null,
    isLoading: true,
    error: null,
  });

  // Перевірка існуючої сесії при завантаженні
  useEffect(() => {
    checkExistingSession();
  }, []);

  // Оновлення останньої активності
  useEffect(() => {
    if (auth.isAuthenticated && auth.user) {
      const interval = setInterval(() => {
        updateLastActivity();
      }, 30000); // Кожні 30 секунд

      return () => clearInterval(interval);
    }
  }, [auth.isAuthenticated]);

  const checkExistingSession = async () => {
    try {
      const sessionData = localStorage.getItem('tetracore_session');
      if (!sessionData) {
        setAuth(prev => ({ ...prev, isLoading: false }));
        return;
      }

      const session = JSON.parse(sessionData);

      // Перевірка чи сесія не застаріла (24 години)
      const sessionAge = Date.now() - new Date(session.loginTime).getTime();
      if (sessionAge > 24 * 60 * 60 * 1000) {
        localStorage.removeItem('tetracore_session');
        setAuth(prev => ({ ...prev, isLoading: false }));
        return;
      }

      // Валідація сесії з сервером
      const isValid = await validateSession(session.sessionId);
      if (isValid) {
        setAuth({
          isAuthenticated: true,
          user: {
            ...session.user,
            loginTime: new Date(session.loginTime),
            lastActivity: new Date(),
          },
          isLoading: false,
          error: null,
        });
      } else {
        localStorage.removeItem('tetracore_session');
        setAuth(prev => ({ ...prev, isLoading: false }));
      }
    } catch (error) {
      console.error('Session check failed:', error);
      localStorage.removeItem('tetracore_session');
      setAuth(prev => ({ ...prev, isLoading: false, error: 'Помилка перевірки сесії' }));
    }
  };

  const validateSession = async (sessionId: string): Promise<boolean> => {
    try {
      const response = await fetch('/api/auth/validate', {
        method: 'POST',
        headers: {
          'Content-Type': 'application/json',
        },
        body: JSON.stringify({ sessionId }),
      });

      return response.ok;
    } catch (error) {
      console.error('Session validation failed:', error);
      return false;
    }
  };

  const login = async (telegramData: TelegramUser): Promise<boolean> => {
    try {
      setAuth(prev => ({ ...prev, isLoading: true, error: null }));

      // Валідація Telegram даних
      if (!validateTelegramAuth(telegramData)) {
        throw new Error('Невалідні дані авторизації Telegram');
      }

      // Відправка даних на сервер для авторизації
      const response = await fetch('/api/auth/telegram', {
        method: 'POST',
        headers: {
          'Content-Type': 'application/json',
        },
        body: JSON.stringify(telegramData),
      });

      if (!response.ok) {
        const errorData = await response.json();
        throw new Error(errorData.message || 'Помилка авторизації');
      }

      const authResult = await response.json();

      const user: User = {
        id: telegramData.id.toString(),
        username: telegramData.username || `user_${telegramData.id}`,
        firstName: telegramData.first_name,
        lastName: telegramData.last_name,
        photoUrl: telegramData.photo_url,
        role: authResult.role || 'viewer',
        permissions: authResult.permissions || [],
        sessionId: authResult.sessionId,
        loginTime: new Date(),
        lastActivity: new Date(),
      };

      // Збереження сесії
      const sessionData = {
        user,
        sessionId: authResult.sessionId,
        loginTime: new Date().toISOString(),
      };

      localStorage.setItem('tetracore_session', JSON.stringify(sessionData));

      setAuth({
        isAuthenticated: true,
        user,
        isLoading: false,
        error: null,
      });

      return true;
    } catch (error) {
      console.error('Login failed:', error);
      setAuth(prev => ({
        ...prev,
        isLoading: false,
        error: error instanceof Error ? error.message : 'Помилка авторизації',
      }));
      return false;
    }
  };

  const logout = async () => {
    try {
      if (auth.user?.sessionId) {
        // Повідомлення сервера про вихід
        await fetch('/api/auth/logout', {
          method: 'POST',
          headers: {
            'Content-Type': 'application/json',
          },
          body: JSON.stringify({ sessionId: auth.user.sessionId }),
        });
      }
    } catch (error) {
      console.error('Logout request failed:', error);
    } finally {
      // Очищення локальних даних
      localStorage.removeItem('tetracore_session');
      setAuth({
        isAuthenticated: false,
        user: null,
        isLoading: false,
        error: null,
      });
    }
  };

  const refreshAuth = async () => {
    if (auth.user?.sessionId) {
      const isValid = await validateSession(auth.user.sessionId);
      if (!isValid) {
        logout();
      }
    }
  };

  const updateLastActivity = () => {
    if (auth.user) {
      const updatedUser = {
        ...auth.user,
        lastActivity: new Date(),
      };

      setAuth(prev => ({
        ...prev,
        user: updatedUser,
      }));

      // Оновлення в localStorage
      const sessionData = localStorage.getItem('tetracore_session');
      if (sessionData) {
        const session = JSON.parse(sessionData);
        session.user.lastActivity = new Date().toISOString();
        localStorage.setItem('tetracore_session', JSON.stringify(session));
      }
    }
  };

  const clearError = () => {
    setAuth(prev => ({ ...prev, error: null }));
  };

  // Валідація Telegram авторизації
  const validateTelegramAuth = (data: TelegramUser): boolean => {
    // Перевірка обов'язкових полів
    if (!data.id || !data.first_name || !data.auth_date || !data.hash) {
      return false;
    }

    // Перевірка часу авторизації (не старше 1 години)
    const authAge = Date.now() / 1000 - data.auth_date;
    if (authAge > 3600) {
      return false;
    }

    return true;
  };

  const contextValue: AuthContextType = {
    auth,
    login,
    logout,
    refreshAuth,
    clearError,
  };

  return (
    <AuthContext.Provider value={contextValue}>
      {children}
    </AuthContext.Provider>
  );
};
